-- run stamp 'wb-teaser-card-s045-rollback'; journal test id 'WB/teaser-card'.
-- Every UPDATE is conditioned on the old value the plan names; every change is journalled
-- in the same transaction, so the audit trail cannot disagree with the data.
\set ON_ERROR_STOP on
BEGIN;

-- The server bounds this transaction itself: a lock wait or a runaway statement raises
-- here, psql stops the script (exit 3) and nothing is kept. A client that gives up does
-- not stop the server - psql has the whole script on its stdin.
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

CREATE TEMP TABLE _teaser_card_plan (
    site_id     UUID NOT NULL,
    column_name TEXT NOT NULL,
    old_value   TEXT,
    new_value   TEXT,
    change_key  TEXT NOT NULL,
    reason      TEXT NOT NULL,
    premise     TEXT NOT NULL,
    evidence    JSONB NOT NULL,
    PRIMARY KEY (site_id, column_name)
) ON COMMIT DROP;

INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('238793b3-c335-4dcf-8155-c9e2d4985e0d'::uuid, 'card_description', 'Three rock markings carry drainage channels that suggest a fluid once flowed. Found in 2016, the markings are not alone: similar rock markings are common across Eastern Anatolia.', 'Drainage channels on three rock markings run toward a canyon. Found in 2016, the channels suggest that fluid once flowed, and similar rock markings are common across Eastern Anatolia.', 'teaser-card-s045-rollback:238793b3-c335-4dcf-8155-c9e2d4985e0d:card_description', 'rollback of teaser-card-s045: card_description ''Drainage channels on three rock markings run toward a canyon. Found in 2016, the channels suggest that fluid once flowed, and similar rock markings are common across Eastern Anatolia.'' restored on Nakhchivan Rock Signs', 'a6ca8f8109abad08c669655393b3041d17d7bcaf97e1c18a8805a55a62700ac2|687fb2147a56416cf1732750963b56c50275e5d32791eb33b5dbd721d7063632|687fb2147a56416cf1732750963b56c50275e5d32791eb33b5dbd721d7063632', '[{"source": "lane WB run wb-shorts-d132-2026-11-07: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-d132-2026-11-07/OUTCOMES.jsonl", "quote": "Three rock markings carry drainage channels that suggest a fluid once flowed. Found in 2016, the markings are not alone: similar rock markings are common across Eastern Anatolia."}, {"source": "lane WB run wb-shorts-d132-2026-11-07: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d132-2026-11-07/OUTCOMES.jsonl", "quote": "there are three rock markings [S2]; the markings carry drainage channels [S2]; the channels suggest that a fluid flowed [S2]; the markings were found in 2016 [S1]; similar rock markings exist elsewhere [S3]; similar rock markings are common across Eastern Anatolia [S3]"}, {"source": "lane WB run wb-shorts-d132-2026-11-07: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d132-2026-11-07/OUTCOMES.jsonl", "quote": "Three rock markings (at this site in Nakhchivan, Azerbaijan) [SUPPORTED: https://dergipark.org.tr/en/download/article-file/747210]; The markings carry drainage channels [SUPPORTED: https://dergipark.org.tr/en/download/article-file/747210]; The drainage channels suggest that a fluid once flowed [SUPPORTED: https://dergipark.org.tr/en/download/article-file/747210]; The markings were found in 2016 [SUPPORTED: https://dergipark.org.tr/en/download/article-file/747210]; The markings are not alone (they belong to a wider group of such rock signs) [SUPPORTED: https://dergipark.org.tr/en/download/article-file/4087425]; Similar rock markings are common across Eastern Anatolia [SUPPORTED: https://dergipark.org.tr/en/download/article-file/747210]"}]'::jsonb),
    ('6814a205-8ebc-46b8-8581-94c1cbb06745'::uuid, 'card_description', 'Shafts follow veins of copper ore, some 15-20 metres into the hillside. Pottery of the Vincha culture confirms the age of the mine, one of the earliest copper mines in Europe.', 'Miners here broke the rock with fire-setting and thermal shock. Shafts follow veins of copper ore, some 15-20 metres into the hillside, in one of the earliest copper mines in Europe.', 'teaser-card-s045-rollback:6814a205-8ebc-46b8-8581-94c1cbb06745:card_description', 'rollback of teaser-card-s045: card_description ''Miners here broke the rock with fire-setting and thermal shock. Shafts follow veins of copper ore, some 15-20 metres into the hillside, in one of the earliest copper mines in Europe.'' restored on Rudna Glava', 'cb06d4c9728722d609f65fcc456d17e1c8a2026a9c4abda81352234fb039bdeb|4cdd3fcf07c0fadf32055479b29cb89ed98c13ffd35823fa1e4714db3af1ab86|4cdd3fcf07c0fadf32055479b29cb89ed98c13ffd35823fa1e4714db3af1ab86', '[{"source": "lane WB run wb-shorts-d132-2026-11-07: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-d132-2026-11-07/OUTCOMES.jsonl", "quote": "Shafts follow veins of copper ore, some 15-20 metres into the hillside. Pottery of the Vincha culture confirms the age of the mine, one of the earliest copper mines in Europe."}, {"source": "lane WB run wb-shorts-d132-2026-11-07: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d132-2026-11-07/OUTCOMES.jsonl", "quote": "the site has mine shafts [S2]; the shafts follow veins of copper ore [S2]; some shafts extend 15-20 metres into the hillside [S2]; pottery of the Vincha culture was found there [S4]; the pottery confirms the age of the mine [S4]; the site is a copper mine [S1]; it is one of the earliest copper mines in Europe [S1]"}, {"source": "lane WB run wb-shorts-d132-2026-11-07: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d132-2026-11-07/OUTCOMES.jsonl", "quote": "Shafts follow veins of ore (at this mine in Serbia) [SUPPORTED: https://www.penn.museum/sites/expedition/the-oldest-copper-metallurgy-in-the-balkans/]; The veins are of copper ore [SUPPORTED: https://www.penn.museum/sites/expedition/the-oldest-copper-metallurgy-in-the-balkans/]; The shafts go some 15-20 metres into the hillside [SUPPORTED: https://www.ccsp.it/wp-content/uploads/2021/03/BCSP13-14_pp77-90.pdf]; Pottery of the Vinča culture was found at the mine [SUPPORTED: https://www.penn.museum/sites/expedition/the-oldest-copper-metallurgy-in-the-balkans/]; The pottery confirms the age of the mine [SUPPORTED: https://www.penn.museum/sites/expedition/the-oldest-copper-metallurgy-in-the-balkans/]; The site is a copper mine [SUPPORTED: https://www.penn.museum/sites/expedition/the-oldest-copper-metallurgy-in-the-balkans/]; It is one of the earliest copper mines in Europe [SUPPORTED: https://www.penn.museum/sites/expedition/the-oldest-copper-metallurgy-in-the-balkans/]"}]'::jsonb),
    ('951c140b-1698-4495-9c6b-c78254c2b4cd'::uuid, 'card_description', 'An upturned tree root sat at the centre of a ring of 55 split oak trunks. Every trunk but one faced its bark outwards, and the salt marsh around the circle later became a freshwater wetland.', 'An upturned tree root sat at the heart of this timber circle. Around the root stood 55 split oak trunks, all but one with bark facing out; a trunk with a narrow Y fork let people in.', 'teaser-card-s045-rollback:951c140b-1698-4495-9c6b-c78254c2b4cd:card_description', 'rollback of teaser-card-s045: card_description ''An upturned tree root sat at the heart of this timber circle. Around the root stood 55 split oak trunks, all but one with bark facing out; a trunk with a narrow Y fork let people in.'' restored on Seahenge', 'eec81a6a1d76648df8b154876d49fed57e42c862d23646f5746b93f6687ae0a7|98aa240c4d6158574fc8d20a875256602b85c08a276fd0c2be733d8b2a9b3862|98aa240c4d6158574fc8d20a875256602b85c08a276fd0c2be733d8b2a9b3862', '[{"source": "lane WB run wb-shorts-d132-2026-11-07: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-d132-2026-11-07/OUTCOMES.jsonl", "quote": "An upturned tree root sat at the centre of a ring of 55 split oak trunks. Every trunk but one faced its bark outwards, and the salt marsh around the circle later became a freshwater wetland."}, {"source": "lane WB run wb-shorts-d132-2026-11-07: checker card_fact_checker:teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d132-2026-11-07/OUTCOMES.jsonl", "quote": "an upturned tree root stood at the centre of the monument [S2]; the root sat inside a ring of trunks [S2, S3]; the ring had 55 trunks [S3]; the trunks were split [S3]; the trunks were oak [S3]; every trunk but one faced its bark outwards [S5]; the circle stood in a salt marsh [S7]; the area around the circle later became a freshwater wetland [S7]"}, {"source": "lane WB run wb-shorts-d132-2026-11-07: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d132-2026-11-07/OUTCOMES.jsonl", "quote": "A tree root sat at the centre of a ring of timbers [SUPPORTED: https://heritage.norfolk.gov.uk/record-details?MNF33771-%27Seahenge%27-Early-Bronze-Age-timber-circle-on-Holme-Beach=]; The tree root at the centre was upturned [SUPPORTED: https://heritage.norfolk.gov.uk/record-details?MNF33771-%27Seahenge%27-Early-Bronze-Age-timber-circle-on-Holme-Beach=]; The ring had 55 trunks [SUPPORTED: https://heritage.norfolk.gov.uk/record-details?MNF33771-%27Seahenge%27-Early-Bronze-Age-timber-circle-on-Holme-Beach=]; The trunks of the ring were oak [SUPPORTED: https://heritage.norfolk.gov.uk/record-details?MNF33771-%27Seahenge%27-Early-Bronze-Age-timber-circle-on-Holme-Beach=]; The oak trunks of the ring were split [SUPPORTED: https://heritage.norfolk.gov.uk/record-details?MNF33771-%27Seahenge%27-Early-Bronze-Age-timber-circle-on-Holme-Beach=]; Every trunk but one faced its bark outwards [SUPPORTED: https://heritage.norfolk.gov.uk/record-details?MNF33771-%27Seahenge%27-Early-Bronze-Age-timber-circle-on-Holme-Beach=]; A salt marsh lay around the circle [SUPPORTED: https://heritage.norfolk.gov.uk/record-details?MNF33771-%27Seahenge%27-Early-Bronze-Age-timber-circle-on-Holme-Beach=]; The salt marsh around the circle later became a freshwater wetland [SUPPORTED: https://heritage.norfolk.gov.uk/record-details?MNF33771-%27Seahenge%27-Early-Bronze-Age-timber-circle-on-Holme-Beach=]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 3;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s045-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s045-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s045-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 3 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s045-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s045-rollback' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
